
(function(root){'use strict';const H=root.Subway238,layer=document.createElement('section');layer.id='subway-destinations238';layer.hidden=true;layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-labelledby','subway-title238');layer.style.cssText='position:absolute;inset:0;z-index:42;background:#07131be8;display:none;align-items:center;justify-content:center;padding:20px;text-align:center;color:#e1ebec';document.querySelector('#cabinet').append(layer);let shown=null,signature='';
function sync(g,isPaused=false){const yes=H.menu(g)&&!isPaused;layer.hidden=!yes;layer.style.display=yes?'flex':'none';if(!yes){shown=null;return;}const sig=H.destinations.map(d=>d.id+':'+d.name).join('|');if(signature!==sig||!layer.firstChild){signature=sig;layer.innerHTML='<div style="max-width:650px"><p style="color:#83cddd">CENTRAL TRANSIT · ON BOARD</p><h2 id="subway-title238">CHOOSE YOUR DESTINATION</h2><p>'+(H.destinations.length?'Choose your next route.':'Destination routes have not been assigned yet. The train is ready for the next part of the story.')+'</p><div id="subway-options238"></div><p style="font-size:13px">D-pad / Arrow keys: select · PS5 × / Enter: confirm</p></div>';const opts=layer.querySelector('#subway-options238');[...H.destinations,{name:'RETURN TO PLATFORM'}].forEach((d,i)=>{const b=document.createElement('button');b.textContent=d.name;b.style.cssText='display:block;margin:14px auto;padding:14px 28px;background:#183c4e;border:2px solid #7ca7b7;color:#f0f6ef;font:700 16px monospace';b.onclick=()=>H.choose(g,i);opts.append(b);});}const buttons=layer.querySelectorAll('button'),fresh=shown!==g.subway238;buttons.forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===g.subway238.selected));b.style.borderColor=i===g.subway238.selected?'#f7d365':'#486879';if(fresh&&i===g.subway238.selected)b.focus({preventScroll:true});});shown=g.subway238;}
root.SubwayUI238={sync};
})(window);
